const msg = items[0].json;

// n8n Gmail Trigger returns headers as a flat object: { 'header-name': 'Header-Name: raw value' }
const headersObj = msg.headers || {};

function getHeader(name) {
  const raw = headersObj[name.toLowerCase()];
  if (!raw) return null;
  const idx = raw.indexOf(':');
  return idx !== -1 ? raw.slice(idx + 1).trim() : raw.trim();
}

// From: prefer n8n's parsed address object if present, fall back to raw header parsing
let displayName = '', senderEmail = '';
if (msg.from && msg.from.value && msg.from.value[0]) {
  displayName = msg.from.value[0].name || '';
  senderEmail = msg.from.value[0].address || '';
} else {
  const fromRaw = getHeader('From') || '';
  const displayNameMatch = fromRaw.match(/^"?([^"<]*)"?\s*<?/);
  displayName = displayNameMatch ? displayNameMatch[1].trim() : '';
  const emailMatch = fromRaw.match(/<([^>]+)>/);
  senderEmail = emailMatch ? emailMatch[1] : fromRaw.trim();
}
const senderDomain = senderEmail.includes('@') ? senderEmail.split('@')[1] : '';

// Originating IP: Received-SPF's client-ip is more reliable than parsing Received here
const receivedSpf = getHeader('Received-SPF') || '';
const clientIpMatch = receivedSpf.match(/client-ip=([0-9a-fA-F:.]+)/);
let originatingIp = clientIpMatch ? clientIpMatch[1] : null;

if (!originatingIp) {
  const receivedRaw = getHeader('Received') || '';
  const ipMatch = receivedRaw.match(/\[([0-9a-fA-F:.]+)\]/);
  originatingIp = ipMatch ? ipMatch[1] : null;
}

// Note: this headers object holds one value per key, so only the LAST "Received" header
// survives if the email had multiple hops — full hop-by-hop chain isn't available here.
// Would need the raw RFC822 source (Gmail API "format=raw") for that.
const receivedRawHeader = getHeader('Received');

// Attachments: if "Download Attachments" is enabled on the Gmail Trigger node, files
// arrive as binary data on this item, not as a payload.parts array.
const attachments = [];
if (items[0].binary) {
  for (const key of Object.keys(items[0].binary)) {
    const bin = items[0].binary[key];
    attachments.push({
      binary_key: key,
      filename: bin.fileName || null,
      mime_type: bin.mimeType || null,
      size: bin.fileSize || null
    });
  }
}

return [{
  json: {
    message_id: msg.id || null,
    thread_id: msg.threadId || null,
    display_name: displayName,
    sender_email: senderEmail,
    sender_domain: senderDomain,
    reply_to: getHeader('Reply-To'),
    return_path: getHeader('Return-Path'),
    originating_ip: originatingIp,
    received_header_raw: receivedRawHeader,
    subject: getHeader('Subject'),
    authentication_results: getHeader('Authentication-Results') || '',
    received_spf: receivedSpf,
    date: getHeader('Date'),
    attachments: attachments
  }
}];

const item = items[0].json;
const authHeader = item.authentication_results || '';
function extractResult(mechanism, text) {
  const re = new RegExp(mechanism + '=([a-zA-Z]+)', 'i');
  const m = text.match(re);
  return m ? m[1].toLowerCase() : 'unknown';
}
return [{
  json: {
    ...item,
    spf_result: extractResult('spf', authHeader),
    dkim_result: extractResult('dkim', authHeader),
    dmarc_result: extractResult('dmarc', authHeader)
  }
}];

const whoisResp = items[0].json;
const original = $('Parse SPF/DKIM/DMARC').item.json;
const whois = whoisResp.WhoisRecord || {};
const createdDate = whois.createdDate || (whois.registryData ? whois.registryData.createdDate : null) || null;
let domainAgeDays = null;
if (createdDate) {
  domainAgeDays = Math.floor((Date.now() - new Date(createdDate).getTime()) / (1000 * 60 * 60 * 24));
}
return [{
  json: {
    ...original,
    domain_created_date: createdDate,
    domain_age_days: domainAgeDays,
    newly_registered_domain: domainAgeDays !== null ? domainAgeDays < 30 : null,
    registrar: whois.registrarName || null
  }
}];

const abuseResp = items[0].json;
const original = $('Parse SPF/DKIM/DMARC').item.json;
const abuseData = abuseResp.data || {};

const brandList = ['paypal.com','microsoft.com','google.com','usps.com','fedex.com','dhl.com','amazon.com','apple.com','netflix.com','bankofamerica.com'];
function levenshtein(a, b) {
  const m = a.length, n = b.length;
  const dp = Array.from({length: m + 1}, () => new Array(n + 1).fill(0));
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
    }
  }
  return dp[m][n];
}
const domain = (original.sender_domain || '').toLowerCase();
let closestBrand = null, closestDistance = Infinity;
for (const brand of brandList) {
  const d = levenshtein(domain, brand);
  if (d < closestDistance) { closestDistance = d; closestBrand = brand; }
}

return [{
  json: {
    ...original,
    abuse_confidence_score: abuseData.abuseConfidenceScore ?? null,
    ip_country: abuseData.countryCode ?? null,
    ip_isp: abuseData.isp ?? null,
    ip_total_reports: abuseData.totalReports ?? null,
    closest_brand_match: closestBrand,
    edit_distance: closestDistance,
    likely_typosquat: closestDistance > 0 && closestDistance <= 3,
    contains_punycode: domain.includes('xn--')
  }
}];

const msg = items[0].json;

// n8n's Gmail Trigger already parses the body — msg.text is clean plain text
let plainText = msg.text || '';

if (!plainText && msg.html) {
  plainText = msg.html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

plainText = plainText
  .replace(/Sent from Outlook for Android.*$/is, '')
  .trim();

return [{
  json: {
    ...msg,
    decoded_html: msg.html || '',
    plain_text_body: plainText
  }
}];

const item = items[0].json;

let rawText = '';

// Extract Gemini/n8n model response
if (item.content?.parts?.[0]?.text) {
  rawText = item.content.parts[0].text;
} 
else if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
  rawText = item.candidates[0].content.parts[0].text;
}

// Clean markdown fences
const cleaned = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch (error) {

  // Try extracting JSON object
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');

  if (start === -1 || end === -1) {
    return [{
      json: {
        status: 'FAILED',
        error: 'Could not find JSON in AI response',
        raw_response: rawText
      }
    }];
  }

  try {
    parsed = JSON.parse(
      cleaned.substring(start, end + 1)
    );
  } catch (error2) {
    return [{
      json: {
        status: 'FAILED',
        error: error2.message,
        raw_response: rawText
      }
    }];
  }
}

// Extract only what you need
const intent = parsed.intent ?? '';
const verdict = parsed.verdict ?? '';
const score = parsed.phishing_score ?? null;
const tone = parsed.tone ?? '';

// Clean final output
return [{
  json: {
    intent: intent,
    verdict: verdict,
    score: score,
    tone: tone
  }
}];

const item = items[0].json;
const text = (item.decoded_html || '') + ' ' + (item.plain_text_body || '');
const urlRegex = /https?:\/\/[^\s"'<>)]+/g;
const found = [...new Set((text.match(urlRegex) || []))];

const shorteners = ['bit.ly','tinyurl.com','t.co','goo.gl','ow.ly','is.gd','buff.ly'];

function shannonEntropy(str) {
  const freq = {};
  for (const ch of str) freq[ch] = (freq[ch] || 0) + 1;
  let entropy = 0;
  const len = str.length;
  for (const ch in freq) {
    const p = freq[ch] / len;
    entropy -= p * Math.log2(p);
  }
  return Math.round(entropy * 100) / 100;
}

return found.map(url => {
  let domain = '';
  try { domain = new URL(url).hostname; } catch (e) { domain = ''; }
  return {
    json: {
      message_id: item.message_id,
      sender_domain: item.sender_domain,
      url: url,
      url_domain: domain,
      entropy: shannonEntropy(url),
      contains_punycode: domain.includes('xn--'),
      is_shortener: shorteners.some(s => domain.includes(s))
    }
  };
});

const item = items[0].json;
const b64 = Buffer.from(item.url).toString('base64');
const urlId = b64.replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
return [{ json: { ...item, url_id: urlId } }];

const scanResult = items[0].json;
const original = $('Compute VT URL ID').item.json;
const vt = $('VT URL Report').item.json;

const vtStats = (vt.data && vt.data.attributes && vt.data.attributes.last_analysis_stats) || null;
const finalUrl = (scanResult.page && scanResult.page.url) || original.url;
const finalDomain = (scanResult.page && scanResult.page.domain) || original.url_domain;
const redirected = finalDomain && original.url_domain && finalDomain !== original.url_domain;

let credentialFormDetected = false;
try {
  const htmlSnippet = JSON.stringify(scanResult).toLowerCase();
  credentialFormDetected = htmlSnippet.includes('type=\"password\"') || htmlSnippet.includes("type='password'");
} catch (e) { /* best effort only */ }

return [{
  json: {
    message_id: original.message_id,
    url: original.url,
    url_domain: original.url_domain,
    entropy: original.entropy,
    contains_punycode: original.contains_punycode,
    is_shortener: original.is_shortener,
    vt_malicious_count: vtStats ? vtStats.malicious : null,
    vt_suspicious_count: vtStats ? vtStats.suspicious : null,
    vt_found: !!vt.data,
    final_url_after_redirect: finalUrl,
    final_domain_after_redirect: finalDomain,
    redirected_to_different_domain: redirected,
    credential_form_detected_heuristic: credentialFormDetected
  }
}];
